begin;
create or replace function public.save_product_billing_mapping(target_facility uuid,target_product uuid,target_service uuid,change_reason text) returns void language plpgsql security definer set search_path='' as $$declare org uuid;old_service uuid;begin if not public.has_privilege('charge_master.write',target_facility) then raise exception 'Not authorized to maintain billing mappings';end if;if length(trim(coalesce(change_reason,'')))<5 then raise exception 'A change reason of at least 5 characters is required';end if;select f.organization_id,p.billing_service_id into org,old_service from public.facilities f join public.products p on p.organization_id=f.organization_id where f.id=target_facility and p.id=target_product for update of p;if org is null then raise exception 'Product not found for this organization';end if;if target_service is not null and not exists(select 1 from public.service_catalog s where s.id=target_service and s.organization_id=org and s.status='active' and s.billable) then raise exception 'Select an active billable service';end if;update public.products set billing_service_id=target_service where id=target_product;insert into public.audit_events(organization_id,facility_id,actor_id,event_type,object_type,object_id,reason,details) values(org,target_facility,auth.uid(),'billing_mapping.product_changed','product',target_product,trim(change_reason),jsonb_build_object('previous_service_id',old_service,'service_id',target_service));end$$;
create or replace function public.save_ward_billing_mapping(target_facility uuid,target_ward uuid,target_service uuid,change_reason text) returns void language plpgsql security definer set search_path='' as $$declare org uuid;old_service uuid;begin if not public.has_privilege('charge_master.write',target_facility) then raise exception 'Not authorized to maintain billing mappings';end if;if length(trim(coalesce(change_reason,'')))<5 then raise exception 'A change reason of at least 5 characters is required';end if;select f.organization_id,w.billing_service_id into org,old_service from public.facilities f join public.wards w on w.facility_id=f.id where f.id=target_facility and w.id=target_ward for update of w;if org is null then raise exception 'Ward not found for this facility';end if;if target_service is not null and not exists(select 1 from public.service_catalog s where s.id=target_service and s.organization_id=org and s.status='active' and s.billable) then raise exception 'Select an active billable service';end if;update public.wards set billing_service_id=target_service where id=target_ward;insert into public.audit_events(organization_id,facility_id,actor_id,event_type,object_type,object_id,reason,details) values(org,target_facility,auth.uid(),'billing_mapping.ward_changed','ward',target_ward,trim(change_reason),jsonb_build_object('previous_service_id',old_service,'service_id',target_service));end$$;
grant execute on function public.save_product_billing_mapping(uuid,uuid,uuid,text) to authenticated;
grant execute on function public.save_ward_billing_mapping(uuid,uuid,uuid,text) to authenticated;
commit;
